        if (/expir.*year|exp.?year|cc.?year/.test(description)) return "cc-exp-year";
        if (/expir|card.?exp|cc.?exp/.test(description)) return "cc-exp";
        if (/cardholder|name.?on.?card|cc.?name/.test(description)) return "cc-name";
